// @generated by:gauntlet run:godseye-e08-independent-gauntlet
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { UsageEngine } from "../packages/core/src/usage.js";
import {
  attemptIntent,
  type E08UsageFixture,
  e08UsageFixture,
  unknownOutcome,
} from "./helpers/e08-usage.js";

describe("E08 immutable trusted usage evidence", () => {
  let f: E08UsageFixture;
  beforeEach(async () => {
    f = await e08UsageFixture();
  });
  afterEach(async () => {
    await f.finish();
    await f.store.close();
  });

  it("T-AC-801 retains a durable scope-derived intent across engine restart before any outcome", async () => {
    await f.reporter.intent(attemptIntent);
    const restarted = new UsageEngine(f.store, { now: f.clock.now });
    const row = (await restarted.overview(f.freshOwner())).attempts[0];
    expect(row).toMatchObject({
      runId: f.task.runId,
      projectId: f.project.id,
      environmentId: f.development.id,
      taskId: f.task.id,
      profileId: f.profile.id,
      evidence: "trusted-broker",
      outcome: null,
      completeness: "pending",
    });
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-801 makes identical intent replay idempotent and rejects conflicting evidence", async () => {
    await f.reporter.intent(attemptIntent);
    await f.reporter.intent(attemptIntent);
    await expect(
      f.reporter.intent({ ...attemptIntent, requestHash: "b".repeat(64) }),
    ).rejects.toThrow();
    expect((await f.usage.overview(f.freshOwner())).attempts).toHaveLength(1);
  });

  it("T-AC-801 rejects an invented run and guest-supplied project attribution", async () => {
    await expect(f.usage.reporter(randomUUID()).intent(attemptIntent)).rejects.toThrow();
    await expect(
      f.reporter.intent({
        ...attemptIntent,
        projectId: f.secondProject.id,
      } as typeof attemptIntent),
    ).rejects.toThrow();
    expect((await f.usage.overview(f.freshOwner())).attempts).toHaveLength(0);
  });

  it("T-AC-802 keeps missing failed stream usage unknown rather than manufacturing zero", async () => {
    const row = await f.record({ ...unknownOutcome, state: "failed" });
    const overview = await f.usage.overview(f.freshOwner());
    expect(row).toMatchObject({
      estimatedMicros: null,
      outcome: { state: "failed", streamed: true, categories: unknownOutcome.categories },
    });
    expect(overview.summary.estimatedMicros).toBeNull();
    expect(overview.summary.providerReportedMicros).toBeNull();
    expect(overview.summary.completeness).not.toBe("complete");
  });

  it("T-AC-802 preserves immutable outcomes and actual retry ancestry", async () => {
    await f.record();
    await f.reporter.outcome(unknownOutcome);
    await expect(f.reporter.outcome({ ...unknownOutcome, state: "succeeded" })).rejects.toThrow();
    await f.reporter.intent({
      ...attemptIntent,
      sequence: 2,
      parentSequence: 1,
      relation: "retry",
      requestHash: "b".repeat(64),
    });
    const rows = (await f.usage.overview(f.freshOwner())).attempts;
    expect(rows).toHaveLength(2);
    expect(rows.find((row) => row.sequence === 2)).toMatchObject({
      parentSequence: 1,
      relation: "retry",
      outcome: null,
    });
  });

  it("T-AC-803 prices all categories independently and distinguishes provider reported cost", async () => {
    const price = await f.putPrice({ cacheWriteTtl: "5m" });
    const row = await f.record({
      ...unknownOutcome,
      state: "succeeded",
      streamed: false,
      categories: { input: 10, output: 20, cacheRead: 30, cacheWrite: 40, reasoning: 50 },
      providerReportedMicros: 777,
      cacheWriteTtl: "5m",
    });
    expect(row).toMatchObject({
      estimatedMicros: 373,
      priceId: price.id,
      outcome: {
        providerReportedMicros: 777,
        cacheWriteTtl: "5m",
        categories: { input: 10, output: 20, cacheRead: 30, cacheWrite: 40, reasoning: 50 },
      },
    });
  });

  it("T-AC-803 rounds positive fractional microcost upward without floating point overflow", async () => {
    await f.putPrice({
      ratesMicrosPerMillion: { input: 1, output: 0, cacheRead: 0, cacheWrite: 0, reasoning: 0 },
    });
    const row = await f.record({
      ...unknownOutcome,
      state: "succeeded",
      categories: { input: 1, output: 0, cacheRead: 0, cacheWrite: 0, reasoning: 0 },
    });
    expect(row?.estimatedMicros).toBe(1);
  });

  it("T-AC-803 never reprices settled evidence after a new immutable revision", async () => {
    const original = await f.putPrice();
    const row = await f.record({
      ...unknownOutcome,
      state: "succeeded",
      categories: { input: 1, output: 0, cacheRead: 0, cacheWrite: 0, reasoning: 0 },
    });
    await f.putPrice({
      revision: "fixture-v2",
      ratesMicrosPerMillion: {
        input: 9_000_000,
        output: 0,
        cacheRead: 0,
        cacheWrite: 0,
        reasoning: 0,
      },
    });
    await expect(
      f.putPrice({
        ratesMicrosPerMillion: {
          input: 9_000_000,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
          reasoning: 0,
        },
      }),
    ).rejects.toThrow();
    expect(
      (await f.usage.overview(f.freshOwner())).attempts.find((entry) => entry.id === row?.id),
    ).toMatchObject({ estimatedMicros: 1, priceId: original.id });
  });

  it("T-AC-803 leaves estimates unknown for expired catalog rates", async () => {
    await f.putPrice();
    f.clock.advance(600_001);
    const row = await f.record({
      ...unknownOutcome,
      state: "succeeded",
      categories: { input: 1, output: 0, cacheRead: 0, cacheWrite: 0, reasoning: 0 },
    });
    expect(row?.estimatedMicros).toBeNull();
  });
});
